  "about_items": [
    {
      "n": "#18·01",
      "text": "The blouse is in fine white polka dots on a muted background, with a classic collar and long sleeves. It’s cut relaxed enough to drape softly over your hips without adding bulk, and the fabric feels light for an autumn office day."
    },
    {
      "n": "#20·35",
      "text": "These jeans are in chocolate, with a wide leg that flows from hip to ankle. The high waist keeps the line vertical, drawing the eye upward to your shoulders and downward to your legs while letting the fabric drape without clinging."
    },
    {
      "n": "#91·41",
      "text": "The loafers are in dark beige suede with a low block heel. They’re understated and comfortable, perfect for walking through an office or stepping out after hours without fuss."
    },
    {
      "n": "#309·41",
      "text": "The shoulder bag is in smooth beige leather with a silver buckle. It’s structured but not stiff, and the long strap lets you carry it comfortably across your body or on your shoulder."
    },
    {
      "n": "#369·40",
      "text": "The vest is in beige with a wrap-style front and a tied belt that falls loosely. It adds warmth without bulk, and its V-neckline elongates your torso while keeping the look neat."
    }
  ]
